    def wrapper(*args, **kwargs):
        if any(isinstance(a, (int, float)) and a < 0 for a in args):
            raise ValueError("argumento negativo")
        return func(*args, **kwargs)
    return wrapper


@contar_chamadas
def somar(a, b):
    return a + b


@validar_positivos
